public static class Solution
{
    public static string TruncateWithEllipsis(string s, int maxLength)
    {
        if (s.Length <= maxLength)
        {
            return s;
        }
        if (maxLength >= 3)
        {
            return s.Substring(0, maxLength - 3) + "...";
        }
        return s.PadLeft(maxLength);
    }
}

