public static class Solution
{
    public static int CountSubstring(string s, string sub)
    {
        if (string.IsNullOrEmpty(sub)) return 0;
        int count = 0;
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == sub[0])
            {
                int j = 1;
                while (j < sub.Length && s[i + j] == sub[j])
                {
                    j++;
                }
                if (j == sub.Length)
                {
                    count++;
                    i += j - 1;
                }
                else
                {
                    i++;
                }
            }
            else
            {
                i++;
            }
        }
        return count;
    }
}

