    public static int CountOccurrences(string text, string pattern)
    {
        if (string.IsNullOrEmpty(pattern)) return 0;
        int count = 0;
        for (int i = 0; i < text.Length; i++)
        {
            if (text.Substring(i, pattern.Length) == pattern)
            {
                count++;
                i += pattern.Length - 1;
            }
        }
        return count;
    }
}

