public record Order(int Id, int CustomerId, decimal Amount);

public static class Solution
{
    public static List<string> CustomerNamesWithOrders(List<Customer> customers, List<Order> orders, decimal minAmount)
    {
        var customersWithOrders = orders
            .Where(o => o.Amount >= minAmount)
            .Select(o => o.CustomerId)
            .ToList();
        var customers = customers
            .Where(c => c.Id != 0)
            .ToList();
        var result = new List<string>();
        foreach (var c in customers)
        {
            if (customersWithOrders.Contains(c.Id))
            {
                result.Add(c.Name);
            }
        }
        return result
            .OrderBy(c => c)
            .Distinct()
            .ToList();
    }
}

