public record Order(string Customer, List<OrderLine> Lines);

public static class Solution
{
    public static decimal OrderTotal(Order order)
    {
        return order.Lines.Sum(l => l.Quantity * l.UnitPrice);
    }

    public static decimal CustomerTotal(IEnumerable<Order> orders, string customer)
    {
        return orders
            .Where(o => string.Equals(o.Customer, customer, StringComparison.OrdinalIgnoreCase))
            .Sum(o => OrderTotal(o))
            .ToString("0.00", System.Globalization.CultureInfo.InvariantCulture);
    }
}

public record Product(string Sku, string Name, string Category, decimal Price);

public static class Solution
{
    public static Product? FindBySku(IEnumerable<Product> products, string sku)
    {
        return products.FirstOrDefault(p => string.Equals(p.Sku, sku, StringComparison.OrdinalIgnoreCase));
    }

    public static Dictionary<string, decimal> CategoryTotals(IEnumerable<Product> products)
    {
        var totals: Dictionary<string, decimal> = new Dictionary<string, decimal>();
        foreach (Product p in products)
        {
            if (string.IsNullOrEmpty(p.Category))
            {
                continue;
            }
            if (totals[p.Category] == 0m)
            {
                totals[p.Category] = 0m;
            }
            totals[p.Category] += p.Price;
        }
        return totals;
    }
}

public record Order(int Id, string Customer, decimal Amount);

public static class Solution
{
    public static decimal TotalForCustomer(IEnumerable<Order> orders, string customer)
    {
        return orders
            .Where(o => string.Equals(o.Customer, customer, StringComparison.OrdinalIgnoreCase))
            .Sum(o => o.Amount);
    }

    public static Order? MostValuableOrder(IEnumerable<Order> orders)
    {
        if (orders.Count() == 0)
        {
            return null;
        }

        return orders
            .Where(o => string.Equals(o.Customer, customer, StringComparison.OrdinalIgnoreCase))
            .OrderByDescending(o => o.Amount)
            .FirstOrDefault();
    }

    public static int CountOrdersAbove(IEnumerable<Order> orders, decimal threshold)
    {
        return orders
            .Where(o => o.Amount > threshold)
            .Count();
    }
}

public record Employee(string Id, string Name, string Department, decimal Salary);

public static class Solution
{
    public static decimal DepartmentPayroll(IEnumerable<Employee> employees, string department)
    {
        return employees
            .Where(e => string.Equals(department, e.Department, StringComparison.OrdinalIgnoreCase))
            .Sum(e => e.Salary);
    }

    public static Employee? HighestPaidInDepartment(IEnumerable<Employee> employees, string department)
    {
        return employees
            .Where(e => string.Equals(department, e.Department, StringComparison.OrdinalIgnoreCase))
            .OrderByDescending(e => e.Salary)
            .FirstOrDefault();
    }

    public static Dictionary<string, decimal> PayrollByDepartment(IEnumerable<Employee> employees)
    {
        var groups = employees
            .Where(e => string.Equals(department, e.Department, StringComparison.OrdinalIgnoreCase))
            .GroupBy(e => e.Department)
            .ToDictionary(g => g.Key, g => DepartmentPayroll(g.Value));
        return groups
            .ToDictionary(g => g.Key, g => DepartmentPayroll(g.Value));
    }
}
